"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97045"],{87467(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.formato_obrigatorio","status":422,"titulo":"Fato de dom\xednio texto precisa declarar o formato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.formato_obrigatorio","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["O fato de tipo de dado texto declara o formato do texto (UNI-REQ-0143). O cadastro de um fato declarado (`POST /api/configuracao/admin/fatos-candidato`) ou a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) de um fato declarado trouxe o `dominio` `TEXTO` com o `formato` ausente, vazio ou com um valor que n\xe3o pertence ao vocabul\xe1rio. Para o formato, as duas situa\xe7\xf5es recebem este mesmo c\xf3digo de erro.","A recusa vem na lista `errors` da resposta, com `field` igual a `formato`. Ela s\xf3 \xe9 dada quando o dom\xednio \xe9 v\xe1lido. Nada \xe9 gravado. No fato de sistema, que s\xf3 aceita mudar o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o e a prote\xe7\xe3o de dados, um formato fora do vocabul\xe1rio tamb\xe9m recebe esta recusa, antes da recusa de [defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)."],"comoResolver":["Informe um destes formatos, escrito exatamente assim, em mai\xfasculas: `LIVRE`, `CPF`, `EMAIL`, `TELEFONE`, `CEP` ou `NOME_PESSOA`. Um fato de texto nunca fica abaixo de `PESSOAL` na prote\xe7\xe3o de dados, o que vale tamb\xe9m para o formato `LIVRE`, que pode conter qualquer coisa: veja [a classifica\xe7\xe3o incompat\xedvel com o dom\xednio do fato](/erros/uniplus.configuracao.fato_candidato.classificacao_abaixo_do_minimo_do_dominio)."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);